mapper.select:
WITH RECURSIVE ast_tree( ast01_class_tree_id , ast01_company_id , ast01_class_tree_nm , ast01_parent_tree_id , ast01_seq , ast01_class_tree_cd , ast01_type_cd , ast01_note , ast01_use_yn , ast01_content , ast01_isin , ast01_item_l_class_cd , ast01_item_m_class_cd , ast01_item_s_class_cd , ast01_account_type , ast01_asset_type , ast01_icam_yn , ast01_detail_cd , ast01_tr_unit , ast01_issue_date , ast01_mat_date , ast01_corp_id , ast01_cur_cd , ast01_depn_year , ast01_depn_rt , ast01_depn_type , ast01_ipo_assign_yn , ast01_item_d_class_cd , ast01_eval_type , depth , path , cycle ) AS ( SELECT ast01_class_tree_id , ast01_company_id , ast01_class_tree_nm , ast01_parent_tree_id , ast01_seq , ast01_class_tree_cd , ast01_type_cd , ast01_note , ast01_use_yn , ast01_content , ast01_isin , ast01_item_l_class_cd , ast01_item_m_class_cd , ast01_item_s_class_cd , ast01_account_type , ast01_asset_type , ast01_icam_yn , ast01_detail_cd , ast01_tr_unit , ast01_issue_date , ast01_mat_date , ast01_corp_id , ast01_cur_cd , ast01_depn_year , ast01_depn_rt , ast01_depn_type , ast01_ipo_assign_yn , ast01_item_d_class_cd , ast01_eval_type , 1 , ARRAY[CAST(a.ast01_parent_tree_id AS varchar) || LPAD(CAST(a.ast01_seq AS varchar),10,'0')||a.ast01_class_tree_cd||LPAD(CAST(a.ast01_class_tree_id AS varchar),15,'0')] , false FROM ast01_class_tree a WHERE 1=1 AND ast01_parent_tree_id = 0 AND ast01_use_yn = 'true'
AND ast01_type_cd = #{typeCode}
AND ast01_asset_type = #{assetType}
AND ast01_company_id = #{companyId} UNION ALL SELECT a.ast01_class_tree_id , a.ast01_company_id , a.ast01_class_tree_nm , a.ast01_parent_tree_id , a.ast01_seq , a.ast01_class_tree_cd , a.ast01_type_cd , a.ast01_note , a.ast01_use_yn , a.ast01_content , a.ast01_isin , a.ast01_item_l_class_cd , a.ast01_item_m_class_cd , a.ast01_item_s_class_cd , a.ast01_account_type , a.ast01_asset_type , a.ast01_icam_yn , a.ast01_detail_cd , a.ast01_tr_unit , a.ast01_issue_date , a.ast01_mat_date , a.ast01_corp_id , a.ast01_cur_cd , a.ast01_depn_year , a.ast01_depn_rt , a.ast01_depn_type , a.ast01_ipo_assign_yn , a.ast01_item_d_class_cd , a.ast01_eval_type , b.depth + 1 , array_append(b.path, CAST(a.ast01_parent_tree_id AS varchar) || LPAD(CAST(a.ast01_seq AS varchar),10,'0')||a.ast01_class_tree_cd||LPAD(CAST(a.ast01_class_tree_id AS varchar),15,'0')) , a.ast01_class_tree_nm = any(b.path) FROM ast01_class_tree a INNER JOIN ast_tree b ON a.ast01_parent_tree_id = b.ast01_class_tree_id WHERE 1=1 AND a.ast01_use_yn = 'true'
AND a.ast01_type_cd = #{typeCode}
AND a.ast01_asset_type = #{assetType}
AND not cycle ) SELECT a.ast01_class_tree_id AS class_tree_id , a.ast01_company_id AS company_id , a.ast01_parent_tree_id AS parent_tree_id , ast01_class_tree_nm ||CASE WHEN ast01_type_cd != 'IT' THEN '' ELSE (CASE WHEN COALESCE(a.ast01_isin,'X') != 'X' THEN ' ('||a.ast01_isin||')' ELSE '' END) END AS class_tree_name , a.ast01_class_tree_cd AS class_tree_code , a.ast01_seq AS seq , a.ast01_type_cd AS type_code , a.ast01_note AS note , a.ast01_use_yn AS use_yn , a.ast01_content AS content , a.ast01_isin AS isin , a.ast01_item_l_class_cd AS item_l_class_code , a.ast01_item_m_class_cd AS item_m_class_code , a.ast01_item_s_class_cd AS item_s_class_code , a.ast01_item_d_class_cd AS item_d_class_code , a.ast01_account_type AS account_type , a.ast01_asset_type AS asset_type , a.ast01_tr_unit AS tr_unit , a.ast01_issue_date AS issue_date , a.ast01_mat_date AS mat_date , a.ast01_corp_id AS corp_id , a.ast01_cur_cd AS cur_code , a.ast01_depn_year AS depn_year , a.ast01_depn_rt AS depn_rate , a.ast01_depn_type AS depn_type , a.ast01_eval_type AS eval_type , f_cdnm('ItemLClassCode', a.ast01_item_l_class_cd, a.ast01_company_id, f_sysdate()) AS item_l_class_name , f_cdnm('ItemMClassCode', a.ast01_item_m_class_cd, a.ast01_company_id, f_sysdate()) AS item_m_class_name , f_cdnm('ItemSClassCode', a.ast01_item_s_class_cd, a.ast01_company_id, f_sysdate()) AS item_s_class_name , f_cdnm('ItemDClassCode', a.ast01_item_d_class_cd, a.ast01_company_id, f_sysdate()) AS item_d_class_name , f_cdnm('AssetEvalType', a.ast01_eval_type, a.ast01_company_id, f_sysdate()) AS eval_type_name , f_cdnm('AccountType', a.ast01_account_type, a.ast01_company_id, f_sysdate()) AS account_name , f_cdnm('AssetType', a.ast01_asset_type, a.ast01_company_id, f_sysdate()) AS asset_name , f_cdnm('DepnType', a.ast01_depn_type, a.ast01_company_id, f_sysdate()) AS depn_type_name , f_get_corp_nm(a.ast01_corp_id) AS corp_name , f_cdnm('CurCode', a.ast01_cur_cd, a.ast01_company_id, f_sysdate()) AS cur_name , f_ast_class_tree_nm_allpath(a.ast01_class_tree_id) AS class_tree_full_name , COALESCE(f_ast_class_tree_nm_allpath(a.ast01_parent_tree_id),'없음') AS parent_tree_full_name , depth AS depth FROM ast_tree a ORDER BY path

