       ( ast01_class_tree_id
       , ast01_company_id
       , ast01_parent_tree_id
       , ast01_class_tree_nm
       , ast01_class_tree_cd
       , ast01_seq
       , ast01_type_cd
       , ast01_note
       , ast01_use_yn
       , ast01_content
       , ast01_isin
       , ast01_item_l_class_cd
       , ast01_item_m_class_cd
       , ast01_item_s_class_cd
       , ast01_item_d_class_cd
       , ast01_account_type
       , ast01_asset_type
       , ast01_tr_unit
       , ast01_issue_date
