UPDATE ast01_class_tree
   SET ast01_class_tree_nm = #{classTreeName}
     , ast01_seq           = #{seq}
     , ast01_use_yn        = #{useYn}
 WHERE ast01_class_tree_id = #{classTreeId}

UPDATE ast01_class_tree
   SET ast01_class_tree_nm = #{classTreeName}
     , ast01_seq           = #{seq}
     , ast01_note          = #{note}
     , ast01_use_yn        = #{useYn}
     , ast01_isin          = #{isin}
     , ast01_asset_type    = #{assetType}
 WHERE ast01_class_tree_id = #{classTreeId}

UPDATE ast01_class_tree
   SET ast01_parent_tree_id = #{parentId}
 WHERE ast01_class_tree_id  = #{classTreeId}

UPDATE ast01_class_tree
   SET ast01_content         = #{content}
     , ast01_item_l_class_cd = #{itemLClassCode}
     , ast01_item_m_class_cd = #{itemMClassCode}
     , ast01_item_s_class_cd = #{itemSClassCode}
     , ast01_item_d_class_cd = #{itemDClassCode}
     , ast01_account_type    = #{accountType}
     , ast01_tr_unit         = #{trUnit}
     , ast01_issue_date      = #{issueDate}
     , ast01_mat_date        = #{matDate}
     , ast01_corp_id         = #{corpId}
     , ast01_cur_cd          = #{curCode}
     , ast01_depn_year       = #{depnYear}
     , ast01_depn_rt         = #{depnRate}
     , ast01_depn_type       = #{depnType}
     , ast01_eval_type       = #{evalType}
 WHERE ast01_class_tree_id   = #{classTreeId}
